#include <stack>
#include <vector>

void use_stack() {
    // Stack uses std::deque by default
    std::stack<int> s;
    s.push(10); // O(1) insertion (LIFO)
    s.push(20);

    int top_val = s.top(); // Access the top (20)
    s.pop();             // Remove the top (O(1))

    // std::stack<int, std::vector<int>> s_vec; // Valid alternative base
    // s.begin(); // ERROR: Adapters do not expose iterators
}
